export const REPOSITORY_URL='https://github.com/stellarator-0647/terra-fate-wheel';
export const INSPIRATION_URL='https://jsdh.de5.net/games/jujutsu-wheel-normal-v1';
export const ISSUES_URL=REPOSITORY_URL+'/issues';
export const COMMUNITY_VERSION='1.30.1';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const FEEDBACK_CATEGORIES=['玩法与平衡','界面与手机适配','问题反馈','其他建议'];

export function issueDraft({category,title,body,device='未注明'}){
 const kind=FEEDBACK_CATEGORIES.includes(category)?category:'其他建议';
 return {title:`[${kind}] ${String(title||'').trim().slice(0,80)}`,body:`## 反馈类型\n${kind}\n\n## 建议或遇到的问题\n${String(body||'').trim().slice(0,1800)}\n\n## 游玩设备\n${device}\n\n## 游戏版本\n${COMMUNITY_VERSION}`};
}
export function issueLink(draft){const url=new URL(ISSUES_URL+'/new');url.searchParams.set('template','suggestion.md');url.searchParams.set('title',draft.title);url.searchParams.set('body',draft.body);if(url.href.length>7500)url.searchParams.delete('body');return url.href;}

export function thanksMarkup(){return `<div class="thanks-note"><div class="eyebrow">TERRA / SPECIAL THANKS</div><p class="thanks-lead">谢谢你走完这段旅程。</p><p>本作品灵感来自于<a href="${INSPIRATION_URL}" target="_blank" rel="noopener noreferrer">咒术回战轮盘网页游戏</a>。感谢原作提供的转盘玩法与成长思路。</p><p>如果你喜欢这份渣作，欢迎到 GitHub 为项目点一个免费的 <strong>Star</strong>。你的建议也会帮助它继续成长。</p><div class="community-actions"><a class="community-link primary" href="${REPOSITORY_URL}" target="_blank" rel="noopener noreferrer">前往 GitHub · Star</a><button data-act="feedback">提出优化意见</button><button data-act="closeThanks" class="ghost">继续查看结局</button></div></div>`;}

export function feedbackMarkup(draft={}){return `<section class="feedback-screen"><header class="pagehead"><div><div class="eyebrow">PRTS / FEEDBACK</div><h1>意见反馈</h1><p class="muted">哪里不顺手，或者有什么新点子？把你的想法留给这个项目。</p></div><button data-act="feedbackBack" class="small">返回</button></header><div class="feedback-layout"><section class="panel feedback-paper"><h2>提出优化意见</h2><p>填写后会生成 GitHub 反馈草稿；登录 GitHub 并确认发布后，意见才会提交，公开可见。</p><form id="feedback-form"><label for="feedback-category">反馈类型<select id="feedback-category" name="category">${FEEDBACK_CATEGORIES.map(c=>`<option ${draft.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label for="feedback-title">一句话概括<input id="feedback-title" name="title" required maxlength="80" value="${esc(draft.title)}" placeholder="例如：手机上希望更容易查看召唤物"></label><label for="feedback-body">详细内容<textarea id="feedback-body" name="body" required minlength="10" maxlength="1800" rows="7" placeholder="请描述遇到的问题、重现步骤，或你希望如何改进。">${esc(draft.body)}</textarea></label><label for="feedback-device">游玩设备<select id="feedback-device" name="device">${['未注明','手机','电脑','平板'].map(d=>`<option ${draft.device===d?'selected':''}>${d}</option>`).join('')}</select></label><div class="community-actions"><button type="submit" class="primary">生成反馈草稿</button><button type="button" data-act="copyFeedback">复制反馈内容</button></div><p class="feedback-draft-note">填写内容只保存在当前浏览器；生成草稿不会自动发布。</p></form><section id="feedback-ready" class="feedback-ready" hidden aria-live="polite"><h3>草稿已准备好</h3><p>下一步：在 GitHub 确认内容并发布。还可以在发布页面补充截图。</p><a id="feedback-send" class="community-link primary" target="_blank" rel="noopener noreferrer">前往 GitHub 确认提交</a></section></section><aside class="panel feedback-guide"><div class="eyebrow">PROJECT / COMMUNITY</div><h2>一起把游戏做得更好</h2><p>可提出数值平衡、技能联动、转盘体验、手机排版等建议。反馈问题时，写清关卡、源石技艺和操作步骤，方便重现。</p><a class="community-link" href="${ISSUES_URL}" target="_blank" rel="noopener noreferrer">查看已有意见</a><a class="community-link" href="${REPOSITORY_URL}" target="_blank" rel="noopener noreferrer">GitHub 项目</a><p class="smalltext muted">没有 GitHub 账号也可以先填写并复制内容，稍后再提交。</p><div class="divider"></div><h3>灵感来源</h3><a href="${INSPIRATION_URL}" target="_blank" rel="noopener noreferrer">咒术回战轮盘网页游戏</a></aside></div></section>`;}

export function readFeedbackDraft(){try{return JSON.parse(localStorage.getItem('terra-feedback-draft')||'{}')||{};}catch{return {};}}
export function bindFeedback(root,notify){const form=root.querySelector('#feedback-form');if(!form)return;const fields=()=>Object.fromEntries(new FormData(form));form.addEventListener('input',()=>{try{localStorage.setItem('terra-feedback-draft',JSON.stringify(fields()));}catch{}root.querySelector('#feedback-ready').hidden=true;});form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const ready=root.querySelector('#feedback-ready'),link=issueLink(issueDraft(fields()));root.querySelector('#feedback-send').href=link;ready.querySelector('p').textContent=new URL(link).searchParams.has('body')?'下一步：在 GitHub 确认内容并发布。还可以在发布页面补充截图。':'内容较长，请先点击“复制反馈内容”，再在 GitHub 粘贴并确认发布。完整草稿仍保存在当前浏览器。';ready.hidden=false;ready.scrollIntoView({behavior:'smooth',block:'nearest'});});root.querySelector('[data-act="copyFeedback"]')?.addEventListener('click',async()=>{if(!form.reportValidity())return;const d=issueDraft(fields());try{await navigator.clipboard.writeText(d.title+'\n\n'+d.body);notify('反馈内容已复制');}catch{notify('复制未成功，可手动选择详细内容复制');}});}
